content:
{
  "root_cause": "The datepicker does not lose focus when the user tabs out of the input field, causing focus to remain trapped inside the datepicker and preventing movement to the next form field.",
  "repair_strategy": "Add a focusout event listener to the datepicker input that hides the datepicker when focus moves to an element outside the datepicker picker element, allowing Tab to navigate to the next form field.",
  "edits": [
    {
      "path": "js/Datepicker.js",
      "sha256": "26c130b5380a4d36ae7de5ca8e06affc4ed327048a689e12fc9a8804eb63b595",
      "before": "      registerListeners(this, [
        keydownListener,
        [inputField, 'focus', onFocus.bind(null, this)],
        [inputField, 'mousedown', onMousedown.bind(null, this)],
        [inputField, 'click', onClickInput.bind(null, this)],
        [inputField, 'paste', onPaste.bind(null, this)],
        // To detect a click on outside, just listening to mousedown is enough,
        // no need to listen to touchstart.
        // (issue #95)
        [document, 'mousedown', onClickOutside.bind(null, this)],
        [window, 'resize', picker.place.bind(picker)]
      ]);",
      "after": "      registerListeners(this, [
        keydownListener,
        [inputField, 'focus', onFocus.bind(null, this)],
        [inputField, 'mousedown', onMousedown.bind(null, this)],
        [inputField, 'click', onClickInput.bind(null, this)],
        [inputField, 'paste', onPaste.bind(null, this)],
        [inputField, 'focusout', (event) => {
          if (!this.picker.element.contains(event.relatedTarget)) {
            this.hide();
          }
        }],
        // To detect a click on outside, just listening to mousedown is enough,
        // no need to listen to touchstart.
        // (issue #95)
        [document, 'mousedown', onClickOutside.bind(null, this)],
        [window, 'resize', picker.place.bind(picker)]
      ]);"
    }
  ],
  "expected_accessibility_effect": "Pressing Tab in the visit date field will move focus to the access notes field, allowing keyboard users to navigate the form sequentially.",
  "functional_risks": [
    "The datepicker may hide prematurely if focus moves to an element that is not inside the picker but is still part of the datepicker interaction (e.g., a custom popup).",
    "If the datepicker is opened programmatically, the focusout listener might interfere with expected behavior."
  ],
  "verification_requirements": [
    "Tab key navigates from visit-date to notes field when datepicker is open.",
    "Shift+Tab key navigates from notes field to visit-date field when datepicker is open.",
    "Datepicker remains open when clicking inside it after tabbing into the input field.",
    "Datepicker closes when tabbing out of the input field to another form field."
  ]
}
